@lru_cache(maxsize=1)
def archive():
    return zipfile.ZipFile(io.BytesIO(base64.b85decode(_PAYLOAD)))
@lru_cache(maxsize=1)
def html():
    z=archive()
    entries={n:[mimetypes.guess_type(n)[0] or 'application/octet-stream',base64.b64encode(z.read(n)).decode()] for n in z.namelist() if n not in ('game.js','game.css','template.html')}
    boot="window.__ASSETS__={};for(const [p,[type,data]] of Object.entries("+json.dumps(entries,separators=(',',':'))+")){const bytes=Uint8Array.from(atob(data),c=>c.charCodeAt(0));window.__ASSETS__[p]=URL.createObjectURL(new Blob([bytes],{type}));}document.getElementById('source').href=window.__ASSETS__['source.zip'];"
    return z.read('template.html').decode().replace('__CSS__',z.read('game.css').decode()).replace('__BOOT__',boot).replace('__JS__',z.read('game.js').decode().replace('</script',r'<\/script'))
def _validated_build(value):
    if not isinstance(value, dict) or value.get('format') != 'underrune-knight-build' or type(value.get('version')) is not int or value['version'] != 1 or type(value.get('chapter')) is not int or value['chapter'] not in (3, 4):
        raise ValueError('이 기사 전투용 빌드가 아닙니다.')
    fields = {}
    for key, maximum in [('name', 60), ('author', 40), ('description', 300)]:
        text = value.get(key)
        if not isinstance(text, str) or len(text.encode('utf-16-le')) // 2 > maximum:
            raise ValueError('빌드 이름·제작자·설명을 확인해 주세요.')
        fields[key] = text.strip()
    if not fields['name']:
        raise ValueError('빌드 이름을 입력해 주세요.')
    fields['author'] = fields['author'] or '이름 없음'
    source = json.loads(archive().read('generated/equipment.json'))['chapters'][str(value['chapter'])]
    loadout = value.get('loadout')
    if not isinstance(loadout, dict) or type(loadout.get('version')) is not int or loadout['version'] != 1 or not isinstance(loadout.get('characters'), dict):
        raise ValueError('장비 구성이 올바르지 않습니다.')
    chars = {}
    for char in range(1, 5):
        slots = loadout['characters'].get(str(char))
        if not isinstance(slots, dict) or not isinstance(slots.get('armor'), list) or len(slots['armor']) != 2:
            raise ValueError('캐릭터 장비 구성이 올바르지 않습니다.')
        for ident, kind in [(slots.get('weapon'), 'weapons'), *[(a, 'armors') for a in slots['armor']]]:
            if type(ident) is not int:
                raise ValueError('장비 번호가 올바르지 않습니다.')
            gear = next((g for g in source[kind] if g['id'] == ident), None)
            if gear is None or (ident != 0 and char not in gear['allowed']):
                raise ValueError('착용할 수 없는 장비가 있습니다.')
        chars[str(char)] = {'weapon': slots['weapon'], 'armor': slots['armor'][:]}
    items = loadout.get('items')
    if not isinstance(items, list) or len(items) > source['bagCapacity'] or any(type(i) is not int or i == 0 or not any(x['id'] == i for x in source['items']) for i in items):
        raise ValueError('아이템 번호 또는 가방 용량이 올바르지 않습니다.')
    return {'format': 'underrune-knight-build', 'version': 1, 'chapter': value['chapter'], **fields, 'loadout': {'version': 1, 'characters': chars, 'items': items[:]}}


def shared_request(request, db_path=None):
    """All visitors to this server share one registry. Never overwrite a claimed word."""
    import os, re, sqlite3, unicodedata
    from contextlib import closing
    from pathlib import Path
    ident = request.get('id', '') if isinstance(request, dict) else ''
    if not isinstance(ident, str) or len(ident) > 100:
        ident = ''
    try:
        if not isinstance(request, dict) or len(json.dumps(request, ensure_ascii=True)) > 24000:
            raise ValueError('요청이 너무 크거나 올바르지 않습니다.')
        word = request.get('code')
        if not isinstance(word, str):
            raise ValueError('단어 코드를 입력해 주세요.')
        word = unicodedata.normalize('NFKC', word.strip()).casefold()
        if not re.fullmatch(r'[가-힣a-z0-9_-]{1,24}', word):
            raise ValueError('코드는 한글·영문·숫자·밑줄·하이픈으로 1~24자를 입력해 주세요.')
        action = request.get('action')
        if action not in ('register', 'lookup'):
            raise ValueError('지원하지 않는 요청입니다.')
        # Validate before opening a write transaction. Store only normalized fields.
        build = _validated_build(request.get('build')) if action == 'register' else None
        data = json.dumps(build, ensure_ascii=False, sort_keys=True, separators=(',', ':')) if build else None
        path = Path(db_path or os.environ.get('KNIGHT_BUILDS_DB') or Path(__file__).resolve().with_name('knight-builds.sqlite3'))
        path.parent.mkdir(parents=True, exist_ok=True)
        with closing(sqlite3.connect(str(path), timeout=10)) as connection, connection:
            connection.execute('CREATE TABLE IF NOT EXISTS builds (code TEXT PRIMARY KEY, data TEXT NOT NULL, created TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)')
            if action == 'register':
                connection.execute('BEGIN IMMEDIATE')
                existing = connection.execute('SELECT data FROM builds WHERE code=?', (word,)).fetchone()
                if existing:
                    if existing[0] != data:
                        raise ValueError('이미 다른 빌드에 사용 중인 코드입니다. 다른 단어를 정해 주세요.')
                else:
                    if connection.execute('SELECT COUNT(*) FROM builds').fetchone()[0] >= 10000:
                        raise ValueError('공유 저장 공간이 가득 찼습니다.')
                    connection.execute('INSERT INTO builds(code,data) VALUES(?,?)', (word, data))
                return {'id': ident, 'ok': True, 'code': word}
            found = connection.execute('SELECT data FROM builds WHERE code=?', (word,)).fetchone()
            if not found:
                raise ValueError('등록되지 않은 코드입니다. 코드와 게임 사이트 주소를 확인해 주세요.')
            return {'id': ident, 'ok': True, 'code': word, 'build': json.loads(found[0])}
    except ValueError as error:
        return {'id': ident, 'ok': False, 'error': str(error)}
    except (OSError, sqlite3.Error):
        return {'id': ident, 'ok': False, 'error': '공용 저장소에 연결하지 못했습니다. 잠시 후 다시 시도해 주세요.'}


def game_html(mode='offline'):
    return html().replace('<script>', '<script>window.__BUILD_MODE__=' + json.dumps(mode) + ';</script><script>', 1)


def run_streamlit():
    import streamlit as st
    import streamlit.components.v1 as components
    import hashlib, os, tempfile
    from pathlib import Path
    st.set_page_config(page_title='기사 & 거슨 전투', layout='wide')
    # Stable component key and directory keep the game iframe alive across requests.
    digest = hashlib.sha256(_PAYLOAD.encode()).hexdigest()[:16]
    directory = Path(tempfile.gettempdir()) / ('knight-component-' + digest)
    directory.mkdir(exist_ok=True)
    index = directory / 'index.html'
    if not index.exists():
        fd, filename = tempfile.mkstemp(dir=directory, suffix='.tmp')
        with os.fdopen(fd, 'w', encoding='utf-8') as file:
            file.write(game_html('streamlit'))
        os.replace(filename, index)
    component = components.declare_component('knight_shared_game', path=str(directory))
    request = component(reply=st.session_state.get('knight_shared_reply'), key='knight_game', default=None)
    if isinstance(request, dict) and request.get('id') and request['id'] != st.session_state.get('knight_shared_done'):
        st.session_state['knight_shared_reply'] = shared_request(request)
        st.session_state['knight_shared_done'] = request['id']
        st.rerun()


def main():
    if '--extract-source' in sys.argv:
        from pathlib import Path
        i=sys.argv.index('--extract-source');p=Path(sys.argv[i+1] if len(sys.argv)>i+1 else 'knight-source.zip');p.write_bytes(archive().read('source.zip'));print(p);return
    if 'google.colab' in sys.modules:
        from IPython.display import HTML,display
        import html as escape_html
        display(HTML('<iframe style="width:100%;height:1050px;border:0" allow="autoplay;fullscreen" srcdoc="'+escape_html.escape(game_html(),quote=True)+'"></iframe>'));return
    try:
        from streamlit.runtime.scriptrunner import get_script_run_ctx
        running=get_script_run_ctx(suppress_warning=True) is not None
    except ImportError:running=False
    if running:
        run_streamlit();return
    from http.server import BaseHTTPRequestHandler,ThreadingHTTPServer
    class Handler(BaseHTTPRequestHandler):
        def do_POST(self):
            from urllib.parse import urlsplit
            if self.path != '/api/builds':
                self.send_error(404);return
            origin = self.headers.get('Origin')
            if origin and urlsplit(origin).netloc != self.headers.get('Host'):
                self.send_error(403);return
            if self.headers.get('Content-Type', '').split(';')[0] != 'application/json':
                self.send_error(415);return
            try:
                length = int(self.headers.get('Content-Length', '0'))
                if not 0 < length <= 24000:
                    self.send_error(413);return
                request = json.loads(self.rfile.read(length))
            except (ValueError, UnicodeDecodeError):
                self.send_error(400);return
            data = json.dumps(shared_request(request), ensure_ascii=False).encode()
            self.send_response(200);self.send_header('Content-Type','application/json; charset=utf-8');self.send_header('Cache-Control','no-store');self.send_header('Content-Length',str(len(data)));self.end_headers();self.wfile.write(data)
        def do_GET(self):
            if self.path.split('?')[0] not in ('/','/index.html'):
                self.send_error(404);return
            data=game_html('http').encode();self.send_response(200);self.send_header('Content-Type','text/html; charset=utf-8');self.send_header('Content-Length',str(len(data)));self.end_headers();self.wfile.write(data)
    port=int(sys.argv[sys.argv.index('--port')+1]) if '--port' in sys.argv else 8000
    print(f'브라우저에서 http://localhost:{port} 를 여세요.',flush=True)
    try:ThreadingHTTPServer(('0.0.0.0',port),Handler).serve_forever()
    except KeyboardInterrupt:pass
if __name__=='__main__':main()
